/**
 * Lazy loader for the world map geometry (src/data/world/countries-50m.json).
 *
 * The file is ~370 KB (~130 KB gzipped), so it is only fetched through a
 * dynamic import: Vite puts it in its own chunk and the US screens never
 * download it. Nothing imports this module yet (phase 1 is data only).
 *
 * Each feature's `id` is the catalog id from src/data/world.ts (ISO alpha-2,
 * or XK / SIACHEN, see WORLD_NOTES.md). The file is generated by
 * scripts/build-world-topo.mjs from world-atlas (Natural Earth, public domain).
 */
import type { GeometryCollection, Topology } from 'topojson-specification';

export type WorldTopology = Topology<{ countries: GeometryCollection }>;

let cached: Promise<WorldTopology> | null = null;

export function loadWorldTopology(): Promise<WorldTopology> {
  cached ??= import('./world/countries-50m.json').then((m) => m.default as unknown as WorldTopology);
  return cached;
}
